<?php
require __DIR__.'/lib.php';
$page=$_GET['page']??'dashboard';
try { db(); db()->query('SELECT id FROM users LIMIT 1'); } catch(Throwable $e) { http_response_code(503); exit('MediCare setup is incomplete: start MySQL, import the full schema.sql, and check the database name and credentials in config.php. See README.md.'); }
$u=user();
if($u && ($page!=='poll' || time()-(int)($_SESSION['last_reminder_worker']??0)>=10)) { try { process_reminders(); $_SESSION['last_reminder_worker']=time(); } catch(Throwable $e){ error_log('Reminder processing: '.$e->getMessage()); } }
if($page==='poll'){
 header('Content-Type: application/json; charset=utf-8');
 if(!$u || $u['role']!=='patient'){http_response_code(403);echo json_encode(['error'=>'Access denied']);exit;}
 $rows=q("SELECT d.id,d.scheduled_at,m.name,m.dosage FROM doses d JOIN medications m ON m.id=d.medication_id WHERE d.patient_id=? AND d.status='pending' AND d.scheduled_at<=NOW() AND (d.remind_at IS NULL OR d.remind_at<=NOW()) ORDER BY d.scheduled_at,d.id",[$u['id']])->fetchAll();
 echo json_encode(['name'=>$u['name'],'reminders'=>$rows]);exit;
}
if($page==='reminder_action'){
 header('Content-Type: application/json; charset=utf-8');
 if($_SERVER['REQUEST_METHOD']!=='POST' || !$u || $u['role']!=='patient'){http_response_code(403);echo json_encode(['error'=>'Access denied']);exit;}
 if(!isset($_POST['csrf']) || !hash_equals(csrf(),(string)$_POST['csrf'])){http_response_code(403);echo json_encode(['error'=>'Session expired. Refresh and sign in again.']);exit;}
 $did=(int)($_POST['dose_id']??0);$action=$_POST['choice']??'';
 if(!in_array($action,['taken','skipped','snooze'],true)){http_response_code(400);echo json_encode(['error'=>'Invalid action']);exit;}
 try {
  db()->beginTransaction();
  $dose=q("SELECT d.id,d.scheduled_at,m.name FROM doses d JOIN medications m ON m.id=d.medication_id WHERE d.id=? AND d.patient_id=? AND d.status='pending' AND d.scheduled_at<=NOW() AND (d.remind_at IS NULL OR d.remind_at<=NOW()) FOR UPDATE",[$did,$u['id']])->fetch();
  if(!$dose){db()->rollBack();http_response_code(409);echo json_encode(['error'=>'This reminder was already answered or postponed.']);exit;}
  if($action==='snooze'){
   q('UPDATE doses SET remind_at=DATE_ADD(NOW(), INTERVAL 5 MINUTE) WHERE id=?',[$did]);
  } else {
   q('UPDATE doses SET status=?,responded_at=NOW(),remind_at=NULL WHERE id=?',[$action,$did]);
   if($action==='skipped') foreach(q('SELECT caregiver_id FROM caregiver_links WHERE patient_id=?',[$u['id']])->fetchAll() as $link)
    q('INSERT IGNORE INTO notifications(recipient_id,dose_id,message) VALUES (?,?,?)',[$link['caregiver_id'],$did,$u['name'].' marked the '.$dose['name'].' dose at '.date('M j, g:i A',strtotime($dose['scheduled_at'])).' as skipped.']);
  }
  db()->commit();log_event((int)$u['id'],'Reminder response: '.$action); echo json_encode(['ok'=>true,'choice'=>$action]);
 }catch(Throwable $e){if(db()->inTransaction()) db()->rollBack();error_log('Reminder response: '.$e->getMessage());http_response_code(500);echo json_encode(['error'=>'Could not save your response. Please try again.']);}
 exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf(); $action=$_POST['action']??'';
 try {
  if($action==='register'){
   $name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$role=$_POST['role']??'';
   if(!$name || strlen($name)>100 || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($email)>190 || strlen($password)<10 || !in_array($role,['patient','caregiver'],true)) throw new Exception('Please provide a valid name, email, role, and password of at least 10 characters.');
   if(q('SELECT id FROM users WHERE email=?',[$email])->fetch()) throw new Exception('An account with this email already exists.');
   q('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)',[$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]); $id=(int)db()->lastInsertId();session_regenerate_id(true);$_SESSION['user_id']=$id;log_event($id,'Account registered');flash('Welcome to MediCare!');go();
  }
  if($action==='login'){
   $email=strtolower(trim($_POST['email']??''));$found=q('SELECT * FROM users WHERE email=?',[$email])->fetch();
   if(!$found || !password_verify($_POST['password']??'', $found['password_hash'])) throw new Exception('Incorrect email or password.');
   session_regenerate_id(true);$_SESSION['user_id']=(int)$found['id'];log_event((int)$found['id'],'Signed in');go();
  }
  $u=require_user();$id=(int)$u['id'];
  if($action==='logout'){log_event($id,'Signed out');$_SESSION=[];session_destroy();header('Location: landing.html');exit;}
  if($action==='add_med'){
   require_role($u,'patient');$name=trim($_POST['name']??'');$dosage=trim($_POST['dosage']??'');$time=$_POST['time']??'';$start=$_POST['start']??'';$end=$_POST['end']??'';
   if(!$name||strlen($name)>120||!$dosage||strlen($dosage)>100||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$time)||!valid_date($start)||($end && (!valid_date($end)||$end<$start))) throw new Exception('Check the medicine, dosage, time, and dates.');
   q('INSERT INTO medications(patient_id,name,dosage,scheduled_time,start_date,end_date) VALUES (?,?,?,?,?,?)',[$id,$name,$dosage,$time.':00',$start,$end?:null]);log_event($id,'Added a medication');process_reminders();flash('Medication added to your daily schedule.');go('medications');
  }
  if($action==='archive_med'){
   require_role($u,'patient');$mid=(int)($_POST['med_id']??0);
   db()->beginTransaction();$changed=q('UPDATE medications SET active=0 WHERE id=? AND patient_id=? AND active=1',[$mid,$id])->rowCount();
   if($changed) q("DELETE FROM doses WHERE medication_id=? AND patient_id=? AND status='pending' AND scheduled_at>NOW()",[$mid,$id]);db()->commit();
   if(!$changed)throw new Exception('Medication not found or already archived.');log_event($id,'Archived a medication');flash('Medication archived. Its previous records are retained.');go('medications');
  }
  if($action==='dose'){
   require_role($u,'patient');$did=(int)($_POST['dose_id']??0);$status=$_POST['status']??'';if(!in_array($status,['taken','missed'],true))throw new Exception('Invalid response.');
   db()->beginTransaction();$d=q("SELECT d.id,d.scheduled_at,m.name FROM doses d JOIN medications m ON m.id=d.medication_id WHERE d.id=? AND d.patient_id=? AND d.status='pending' AND d.scheduled_at<=NOW() FOR UPDATE",[$did,$id])->fetch();
   if(!$d){db()->rollBack();throw new Exception('This dose is not due or has already been answered.');}
   q('UPDATE doses SET status=?,responded_at=NOW() WHERE id=?',[$status,$did]);
   if($status==='missed'){foreach(q('SELECT caregiver_id FROM caregiver_links WHERE patient_id=?',[$id])->fetchAll() as $link) q('INSERT IGNORE INTO notifications(recipient_id,dose_id,message) VALUES (?,?,?)',[$link['caregiver_id'],$did,$u['name'].' marked the '.$d['name'].' dose at '.date('M j, g:i A',strtotime($d['scheduled_at'])).' as missed.']);}
   db()->commit();log_event($id,'Marked a dose '.$status);flash('Dose marked '.$status.'.');go('dashboard');
  }
  if($action==='link'){
   require_role($u,'patient');$email=strtolower(trim($_POST['email']??''));$c=q("SELECT id FROM users WHERE email=? AND role='caregiver'",[$email])->fetch();if(!$c)throw new Exception('No caregiver account found for that email.');
   q('INSERT IGNORE INTO caregiver_links(patient_id,caregiver_id) VALUES (?,?)',[$id,$c['id']]);log_event($id,'Linked a caregiver');flash('Caregiver linked. They can now view your medication and adherence information.');go('caregivers');
  }
  if($action==='unlink'){
   require_role($u,'patient');q('DELETE FROM caregiver_links WHERE patient_id=? AND caregiver_id=?',[$id,(int)($_POST['caregiver_id']??0)]);log_event($id,'Removed a caregiver link');flash('Caregiver access removed.');go('caregivers');
  }
  if($action==='read_notification'){require_role($u,'caregiver');q('UPDATE notifications SET is_read=1 WHERE id=? AND recipient_id=?',[(int)($_POST['notification_id']??0),$id]);go('notifications');}
  if($action==='delete_user'){
   require_role($u,'admin');$target=(int)($_POST['user_id']??0);$v=q("SELECT id FROM users WHERE id=? AND role IN ('patient','caregiver')",[$target])->fetch();if(!$v)throw new Exception('Account not found.');
   q('DELETE FROM users WHERE id=?',[$target]);log_event($id,'Deleted a patient or caregiver account');flash('Account and related records deleted.');go('accounts');
  }
  if($action==='reset_password'){
   require_role($u,'admin');$target=(int)($_POST['user_id']??0);$password=$_POST['new_password']??'';if(strlen($password)<10)throw new Exception('Password must be at least 10 characters.');
   $changed=q("UPDATE users SET password_hash=? WHERE id=? AND role IN ('patient','caregiver')",[password_hash($password,PASSWORD_DEFAULT),$target])->rowCount();if(!$changed)throw new Exception('Account not found.');log_event($id,'Reset an account password');flash('Password reset. Share it securely with the account owner.');go('accounts');
  }
  throw new Exception('Unknown action.');
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$message=$e instanceof PDOException?'Could not complete the request. Please check the data and try again.':$e->getMessage();flash($message,'error');go(in_array($page,['login','register','medications','caregivers','accounts'],true)?$page:'dashboard');}
}
if(!$u && !in_array($page,['login','register'],true)) go('login');
if($u && in_array($page,['login','register'],true)) go();
if($u){$allowed=['dashboard','profile','reports'];if($u['role']==='patient')$allowed=array_merge($allowed,['medications','caregivers']);if($u['role']==='caregiver')$allowed=array_merge($allowed,['patients','notifications']);if($u['role']==='admin')$allowed=array_merge($allowed,['accounts','activity','registry']);if(!in_array($page,$allowed,true)){http_response_code(404);exit('Page not found.');}}
function weekly_chart(int $patientId): void {
 $week=(string)($_GET['week']??'');
 $selected=valid_date($week)?new DateTimeImmutable($week):new DateTimeImmutable('today');
 $monday=$selected->modify('monday this week')->setTime(0,0); $next=$monday->modify('+7 days');
 $rows=q("SELECT DATE(scheduled_at) day, status, COUNT(*) amount FROM doses WHERE patient_id=? AND scheduled_at>=? AND scheduled_at<? GROUP BY DATE(scheduled_at),status",[$patientId,$monday->format('Y-m-d H:i:s'),$next->format('Y-m-d H:i:s')])->fetchAll();
 $counts=[];foreach($rows as $row) $counts[$row['day']][$row['status']]=(int)$row['amount'];
 $days=[];$totals=['taken'=>0,'missed'=>0,'skipped'=>0,'pending'=>0];
 for($i=0;$i<7;$i++) { $day=$monday->modify('+' . $i . ' days');$c=['taken'=>0,'missed'=>0,'skipped'=>0,'pending'=>0];foreach(($counts[$day->format('Y-m-d')]??[]) as $k=>$v)if(array_key_exists($k,$c))$c[$k]=$v;foreach($c as $k=>$v)$totals[$k]+=$v;$days[]=['date'=>$day,'counts'=>$c,'total'=>array_sum($c)]; }
 $answered=$totals['taken']+$totals['missed']+$totals['skipped'];$rate=$answered?round(100*$totals['taken']/$answered):null;
 $nav=['page'=>(string)($_GET['page']??'dashboard')];if(isset($_GET['patient']))$nav['patient']=(int)$_GET['patient'];
 $previous='index.php?'.http_build_query(array_merge($nav,['week'=>$monday->modify('-7 days')->format('Y-m-d')]));
 $following='index.php?'.http_build_query(array_merge($nav,['week'=>$next->format('Y-m-d')]));
 ?>
 <section class="panel weekly-panel" aria-label="Weekly medication adherence chart">
 <div class="weekly-heading"><div><span class="eyebrow">MONDAY TO SUNDAY</span><h2>Weekly adherence</h2><p><?=h($monday->format('M j'))?> – <?=h($next->modify('-1 day')->format('M j, Y'))?></p></div><div class="week-nav"><a class="button tiny secondary" href="<?=h($previous)?>" aria-label="Previous week">← Previous</a><a class="button tiny secondary" href="<?=h($following)?>" aria-label="Next week">Next →</a></div></div>
 <div class="weekly-summary"><div><strong><?= $rate===null?'—':h($rate).'%' ?></strong><span>Weekly adherence</span></div><p><?=h($totals['taken'])?> taken of <?=h($answered)?> answered doses<br><small>Pending doses are excluded from this percentage.</small></p></div>
 <div class="weekly-legend" aria-label="Chart legend"><span><i class="legend-dot taken"></i>Taken</span><span><i class="legend-dot missed"></i>Missed</span><span><i class="legend-dot skipped"></i>Skipped</span><span><i class="legend-dot pending"></i>Pending</span></div>
 <div class="chart-wrap"><div class="axis" aria-hidden="true"><span>100%</span><span>50%</span><span>0%</span></div><div class="bars" role="list" aria-label="Daily dose status as a share of each day's recorded schedule">
 <?php foreach($days as $d): $c=$d['counts'];$total=$d['total']; $label=$d['date']->format('l, M j').': '.$c['taken'].' taken, '.$c['missed'].' missed, '.$c['skipped'].' skipped, '.$c['pending'].' pending';?>
 <div class="day-bar" role="listitem" aria-label="<?=h($label)?>" title="<?=h($label)?>"><div class="bar-area"><div class="bar-stack"><?php if($total): foreach(['pending','skipped','missed','taken'] as $k):if(!$c[$k])continue;?><span class="bar-segment <?=h($k)?>" style="height:<?=h(round(100*$c[$k]/$total,3))?>%"></span><?php endforeach; else:?><span class="bar-empty">—</span><?php endif;?></div></div><strong><?=h($d['date']->format('D'))?></strong><small><?=h($d['date']->format('j M'))?></small></div>
 <?php endforeach;?></div></div>
 <p class="small weekly-note">Each bar shows the share of recorded scheduled doses for that day. A dash means no records yet; future dates appear when doses are generated. A pending reminder does not mean a dose was taken or missed.</p>
 <details class="weekly-details"><summary>View daily counts</summary><div class="table-wrap"><table><thead><tr><th>Day</th><th>Taken</th><th>Missed</th><th>Skipped</th><th>Pending</th></tr></thead><tbody><?php foreach($days as $d):?><tr><td><?=h($d['date']->format('D, M j'))?></td><?php foreach(['taken','missed','skipped','pending'] as $k):?><td><?=h($d['counts'][$k])?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></details>
 </section>
 <?php
}
function summary_html(int $pid, string $part='all'): void { $s=insights($pid); if($part==='all' || $part==='stats'): ?>
<div class="stats"><div class="stat"><span>Adherence · last 30 days</span><strong><?= $s['rate']===null?'—':h($s['rate']).'%' ?></strong><small>taken ÷ answered doses</small></div><div class="stat"><span>Taken</span><strong><?=h($s['taken'])?></strong><small>recorded doses</small></div><div class="stat"><span>Missed / skipped</span><strong><?=h($s['missed'])?> / <?=h($s['skipped'])?></strong><small>recorded doses</small></div></div>
<?php endif; if($part==='all' || $part==='insight'): ?><div class="panel insight"><span class="eyebrow">✳ &nbsp; AI-ASSISTED SUMMARY </span><h3>Understanding your routine</h3>
<?php if(!$s['total']): ?><p>No answered doses in the past 30 days yet. Your summary will appear as you record doses.</p><?php else: ?><p><?=h($s['taken'])?> of <?=h($s['total'])?> recorded doses were taken in the last 30 days (<?=h($s['rate'])?>%). <?php if($s['pattern']): ?>The most common missed or skipped hour was around <?=h(date('g A',strtotime(sprintf('%02d:00:00',$s['pattern']['hour']))))?> (<?=h($s['pattern']['n'])?> missed or skipped).<?php else: ?>No missed or skipped doses were recorded in this period.<?php endif; ?></p><p>Experimental next-dose missed estimate: <strong><?=h($s['risk'])?>%</strong>. This illustrative model was trained on synthetic data, not real patients, and is not clinically validated. Do not use this estimate for medical decisions.</p><?php endif; ?><p class="small">Patterns and summaries are descriptive, not medical advice. Discuss medication questions with a healthcare professional.</p></div><?php endif; if($part==='all' || $part==='weekly') weekly_chart($pid); }
function doses_table(array $rows, bool $patient=false, bool $canAct=true): void { if(!$rows){echo '<div class="empty">No doses to show yet.</div>';return;} ?><p class="table-hint">Swipe sideways to view the full table →</p><div class="table-wrap"><table><thead><tr><th>Scheduled</th><th>Medicine</th><?php if(!$patient):?><th>Patient</th><?php endif;?><th>Status</th><?php if($patient):?><th>Action</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h(date('M j, Y · g:i A',strtotime($r['scheduled_at'])))?></td><td><strong><?=h($r['name'])?></strong><br><span class="muted"><?=h($r['dosage'])?></span></td><?php if(!$patient):?><td><?=h($r['patient_name'])?></td><?php endif;?><td><span class="badge <?=h($r['status'])?>"><?=h(ucfirst($r['status']))?></span></td><?php if($patient):?><td><?php if($canAct && $r['status']==='pending' && strtotime($r['scheduled_at'])<=time()):?><form method="post" class="inline"><?=token()?><input type="hidden" name="action" value="dose"><input type="hidden" name="dose_id" value="<?=h($r['id'])?>"><button class="button tiny" name="status" value="taken">Taken</button><button class="button tiny secondary" name="status" value="missed">Missed</button></form><?php else:?>—<?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php }
function nav_icon(string $key): string {
 $paths=[
  'dashboard'=>'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  'medications'=>'<path d="M8 16 16 8a4.2 4.2 0 0 0-6-6L2 10a4.2 4.2 0 0 0 6 6Z" transform="translate(3 3)"/><path d="m9 9 6 6"/>',
  'caregivers'=>'<path d="M20.8 5.6a4.7 4.7 0 0 0-6.6 0L12 7.8 9.8 5.6a4.7 4.7 0 0 0-6.6 6.6L12 21l8.8-8.8a4.7 4.7 0 0 0 0-6.6Z"/>',
  'patients'=>'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.9M16 3.2a4 4 0 0 1 0 7.7"/>',
  'notifications'=>'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 20h4"/>',
  'accounts'=>'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2"/>',
  'registry'=>'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M9 3h6v3H9zm0 9h6m-3-3v6"/>',
  'activity'=>'<path d="M3 12h4l3-7 4 14 3-7h4"/>',
  'reports'=>'<path d="M4 20h16M7 17V9m5 8V4m5 13v-5"/>',
  'profile'=>'<circle cx="12" cy="8" r="3.5"/><path d="M5 20a7 7 0 0 1 14 0"/>'
 ];
 return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$key]??'').'</svg>';
}
